def audit_cloud_resources_15(resources: list) -> list:
    # Cloud resource tag and compliance verification for Cloud Security, Cost Optimization & High Availability / DR
    non_compliant = []
    required_tags = {'Environment', 'Owner', 'Project'}
    for r in resources:
        tags = set(r.get('Tags', {}).keys())
        if not required_tags.issubset(tags):
